def maxPathSum(root):
    global max_sum
    max_sum = float('-inf')
    def max_gain(node):
        if not node:
            return 0
        left = max(max_gain(node.left), 0)
        right = max(max_gain(node.right), 0)
        global max_sum
        max_sum = max(max_sum, node.val + left + right)
        return node.val + max(left, right)
    max_gain(root)
    return max_sum

